(7029317, 1066471, 124982, '<td valign="top">I''m going to go out on a limb here and say this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=101668" rel="nofollow" target="_blank">Ammie</a>? Image has the feel of an African sun. Wonderfully golden and warm. Lovely landscape.</td>', 'I''m going to go out on a limb here and say this is  Ammie? Image has the feel of an African sun. Wonderfully golden and warm. Lovely landscape.', '2013-04-29 21:45:43.000000', NULL, 1),
(7029321, 1065243, 124982, '<td valign="top">This has the feel of an <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=123833" rel="nofollow" target="_blank">Mnet</a> image in terms of composition and processing. Lovely rural/suburban landscape. Can''t go wrong with fog!</td>', 'This has the feel of an  Mnet image in terms of composition and processing. Lovely rural/suburban landscape. Can''t go wrong with fog!', '2013-04-29 21:46:46.000000', NULL, 1),
