(7029324, 1066561, 124982, '<td valign="top">Lovely slice of Autumn! Just perfect colors and lighting.</td>', 'Lovely slice of Autumn! Just perfect colors and lighting.', '2013-04-29 21:48:37.000000', NULL, 1),
(7029330, 1066387, 124982, '<td valign="top">Well. Okay then. I really don''t know what to say. I''ve typed and deleted my comment over and over. I''ll just say this. I have only EVER given 5 10''s. This is one of them. The composition absolutely rocks. The road separating the peaceful house as the tempers barrels towards is perfect! Such a poignant take on the saying of the calm before the storm. And the processing. Good gracious, man! I MUST know how you did that sky and clouds. I have not seen something like this in a long, long time. Thank you for this. Really. If this doesn''t end up with a Blue, I will be STUNNED. 10 + favourite.</td>', 'Well. Okay then. I really don''t know what to say. I''ve typed and deleted my comment over and over. I''ll just say this. I have only EVER given 5 10''s. This is one of them. The composition absolutely rocks. The road separating the peaceful house as the tempers barrels towards is perfect! Such a poignant take on the saying of the calm before the storm. And the processing. Good gracious, man! I MUST know how you did that sky and clouds. I have not seen something like this in a long, long time. Thank you for this. Really. If this doesn''t end up with a Blue, I will be STUNNED. 10 + favourite.', '2013-04-29 21:53:49.000000', NULL, 1),
(7029332, 1066608, 124982, '<td valign="top">This speaks of summers long gone and forgotten. Lovely capture of Autumn!</td>', 'This speaks of summers long gone and forgotten. Lovely capture of Autumn!', '2013-04-29 21:54:31.000000', NULL, 1),
