(7029659, 1066663, 61396, '<td valign="top">Nice. Reminds me of a recent <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=116575" rel="nofollow" target="_blank">nickyb</a> image.</td>', 'Nice. Reminds me of a recent  nickyb image.', '2013-04-30 12:49:49.000000', NULL, 1),
