(7030362, 1066328, 12611, '<td valign="top">Congrats- with the Point and shoot no less. (In fact, I think you should stick solely to point and shoot cameras and your sister''s iphone!)</td>', 'Congrats- with the Point and shoot no less. (In fact, I think you should stick solely to point and shoot cameras and your sister''s iphone!)', '2013-05-01 10:33:58.000000', NULL, 0),
(7030380, 1066611, 161383, '<td valign="top">wow, amazing!!</td>', 'wow, amazing!!', '2013-05-01 11:19:12.000000', NULL, 0),
(7030383, 1066237, 159931, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by CNovack:</b></div><hr/><i> Voted earlier coming back to comment.<br/> <br/>Very cool study of lines and shadows. The tree/bush branches are silhouettes that pop off the white snowy ground. The composition as it stands speaks more strongly of winter and not autumn. Perhaps if there was just one single leaf on the ground between the branches a strong visual connection to Autumn could be made. </i></td></tr></table> <br/> <br/>Thanks... your comment was very helpful</td>', 'Originally posted by CNovack: Voted earlier coming back to comment. Very cool study of lines and shadows. The tree/bush branches are silhouettes that pop off the white snowy ground. The composition as it stands speaks more strongly of winter and not autumn. Perhaps if there was just one single leaf on the ground between the branches a strong visual connection to Autumn could be made.   Thanks... your comment was very helpful', '2013-05-01 11:28:39.000000', NULL, 0),
(7030384, 1066387, 35357, '<td valign="top">Three 1''s, wow, haters be hatin''.</td>', 'Three 1''s, wow, haters be hatin''.', '2013-05-01 11:30:23.000000', NULL, 0),
