(7030458, 1066387, 92577, '<td valign="top">3 ribbons out of 10 entries is a pretty good hit rate (not to mention there colours!)<br/>congrats</td>', '3 ribbons out of 10 entries is a pretty good hit rate (not to mention there colours!)congrats', '2013-05-01 14:08:22.000000', NULL, 0),
